    .din4         (  ),
    .din4_mx      (  ),
    .we4          ( 1'b0),
    .we4_mx       (  ),
    
    // dump 5
    .dout5        ( 8'd0 ),
    .addr5        ( 1'b0 ),
    .addr5_mx     (  ),
    // restore
    .din5         (  ),
    .din5_mx      (  ),
    .we5          ( 1'b0),
    .we5_mx       (  ),
    
    .ioctl_addr ( ioctl_addr[23:0] ),
    .ioctl_ram  ( ioctl_ram ),
    .ioctl_aux  ( ioctl_aux ),
    .ioctl_wr   ( ioctl_wr  ),
`ifdef JTFRAME_IOCTL_RD
    .ioctl_din  ( ioctl_din ),
`else
    .ioctl_din  (           ),
`endif
    .ioctl_dout ( ioctl_dout)
);




// Clock enable generation
// 24000000 = 48000000*1/2 Hz from clk
`ifdef VERILATOR_KEEP_CEN /* verilator tracing_on */ `else /* verilator tracing_off */ `endif
jtframe_gated_cen #(.W(2),.NUM(1),.DEN(2),.MFREQ(48000)) u_cen0_clk(
    .rst    ( rst          ),
    .clk    ( clk ),
    .busy   ( 1'b0    ),
    .cen    ( { cen12, cen24 } ),
    .fave   (              ),
    .fworst (              )
); /* verilator tracing_off */

// 3579544 = 48000000*4808/64473 Hz from clk
`ifdef VERILATOR_KEEP_CEN /* verilator tracing_on */ `else /* verilator tracing_off */ `endif
jtframe_gated_cen #(.W(2),.NUM(4808),.DEN(64473),.MFREQ(48000)) u_cen1_clk(
    .rst    ( rst          ),
    .clk    ( clk ),
    .busy   ( 1'b0    ),
    .cen    ( { cen_fm2, cen_fm } ),
    .fave   (              ),
    .fworst (              )
); /* verilator tracing_off */

