    .p1     ( 30'h0), 
    .p2     ( 30'h0), 
    .p3     ( 30'h0), 
    .p4     ( 30'h0), 
    .p5     ( 30'h0), 
    .g0     ( 8'h80 ), // 1.00  snd
    .g1     ( 8'h00 ), // 0.00 
